from collections import defaultdict
def multi(col):
    d=defaultdict(set)
    for a,i in zip(h[col],h.hgnc_id):
        if isinstance(a,str):
            for x in a.split('|'): d[x.strip().upper()].add(i)
    return {k:next(iter(v)) for k,v in d.items() if len(v)==1}
prev=multi('prev_symbol'); ali=multi('alias_symbol')
def sym2id(s):
    s=s.strip().upper()
    return appr.get(s) or prev.get(s) or ali.get(s)
def sm_ids(f):
    ids=[];on=False
    for l in gzip.open(R+f,'rt'):
        if l.startswith('!series_matrix_table_begin'): on=True; continue
