        if on: ids.append(l.split('\t')[0].strip('"'))
    return set(ids[1:])
def annot(f):
    L=gzip.open(R+f,'rt',errors='replace').read().split('\n')
    i=[k for k,l in enumerate(L) if l.startswith('ID\t')][0]
    e=[k for k,l in enumerate(L) if l.startswith('!platform_table_end')]
    return pd.read_csv(io.StringIO('\n'.join(L[i:e[0] if e else None])),sep='\t',dtype=str)
